it('passes an undefined rejection to onError as an Error cause (spec: specs/hal-engine-config-hooks/spec.md#9)', async () => {
  const provider: AIProvider = {
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> {
